test('sums finite numbers', () => {
  expect(total([2, 3])).toBe(5);
  expect(total([-2, -3])).toBe(-5);
  expect(total([])).toBe(0);
});

test('rejects nonnumeric entries', () => {
  expect(() => total(['invalid'])).toThrow(TypeError);
  expect(() => total([NaN])).toThrow(TypeError);
  expect(() => total([Infinity])).toThrow(TypeError);
});

